def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to separate build metadata
        version_part, _, _ = v.partition('+')

        # Split by '-' to separate pre-release
        if '-' in version_part:
            base_part, pre_release = version_part.split('-', 1)
        else:
            base_part = version_part
            pre_release = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        pre_release_identifiers = []
        if pre_release:
            identifiers = pre_release.split('.')
            for identifier in identifiers:
                if identifier.isdigit():
                    pre_release_identifiers.append((0, int(identifier)))
                else:
                    pre_release_identifiers.append((1, identifier))

        return (major, minor, patch, pre_release_identifiers)

    def sort_key(v):
        major, minor, patch, pre_release_identifiers = parse_version(v)
        # Versions with pre-release sort before versions without
        # By using (False, ...) for with pre-release and (True, ...) for without
        has_no_prerelease = len(pre_release_identifiers) == 0
        return (major, minor, patch, has_no_prerelease, pre_release_identifiers)

    # Stable sort to maintain input order for equal precedence versions
    return sorted(versions, key=sort_key)

